import { tags } from "typia";

import { IShoppingMallInventoryHealthProductBreakdown } from "./IShoppingMallInventoryHealthProductBreakdown";

/**
 * Comprehensive inventory health report summarizing the status of all product
 * inventory across the platform. Contains aggregated metrics for inventory
 * health scoring, product-level breakdowns, and recommendations for inventory
 * replenishment.
 *
 * This report is generated by analyzing the inventory quantities and
 * availability status of all product variants across the platform, combined
 * with recent sales trends to provide actionable insights for procurement and
 * inventory management teams. The inventory health score provides a
 * standardized metric for evaluating overall supply chain efficiency and
 * identifying critical inventory issues. As part of administrative analytics,
 * this report enables proactive inventory planning to prevent stockouts, reduce
 * overstocking, and optimize warehouse operations.
 *
 * All metrics are calculated dynamically from the
 * shopping_mall_product_variant_inventory table and correlated with the
 * shopping_mall_product_variants table to provide accurate inventory health
 * assessments.
 *
 * This schema represents the complete response format for the GET
 * /shoppingMall/admin/analytics/inventory/health endpoint, used exclusively by
 * administrators for strategic inventory management decisions.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallInventoryHealthReport = {
  /**
   * Normalized inventory health score calculated as percentage of variants
   * with sufficient stock relative to sales volume over the past 30 days. 0
   * indicates critical shortage, 100 indicates optimal inventory levels
   * across all products.
   *
   * This score is calculated by comparing the current inventory levels
   * against the sales velocity of each product variant over the past 30 days.
   * The scoring algorithm considers both absolute quantity and demand
   * patterns, providing a single metric that reflects overall inventory
   * efficiency. A score below 30 indicates widespread risk of stockouts
   * across the inventory, while scores above 80 indicate optimal inventory
   * levels with healthy buffers against demand fluctuations. This metric
   * allows administrators to quickly assess the health of the entire product
   * catalog without examining each product individually.
   */
  overall_health_score: number & tags.Minimum<0> & tags.Maximum<100>;

  /**
   * Total number of distinct products evaluated in this inventory health
   * analysis.
   *
   * This count represents all unique products in the catalog, regardless of
   * the number of variants each product has. Each product is counted only
   * once, even if it has multiple variants (different colors, sizes, etc.).
   * This metric provides context for the scale of the inventory analysis and
   * helps administrators understand how comprehensive the inventory health
   * assessment is. A higher number indicates more extensive coverage of the
   * product catalog in the analysis.
   */
  total_products_analyzed: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Count of products that have one or more variants with inventory below the
   * predefined threshold for sufficient stock levels.
   *
   * This metric identifies products at risk of stockouts based on predefined
   * inventory thresholds that are calculated based on historical sales data.
   * A product is counted in this metric if ANY of its variants fall below
   * their respective inventory thresholds. These thresholds are determined by
   * the system's automatic inventory optimization algorithm, which considers
   * historical sales patterns, lead times from suppliers, and seasonal demand
   * variations. A high count indicates potential supply chain vulnerabilities
   * and the need for immediate replenishment actions.
   */
  products_with_low_stock_alerts: number & tags.Type<"int32"> & tags.Minimum<0>;

  /**
   * Count of products where every variant has zero inventory quantity and is
   * therefore completely out of stock.
   *
   * This metric is critical for identifying products that have completely
   * exhausted their inventory levels across all available variants. Unlike
   * products with low stock alerts, these products have no remaining stock of
   * any variant, which means customers will be unable to purchase these
   * products at all. This has direct impact on revenue loss and customer
   * satisfaction. Products in this category require immediate attention from
   * procurement teams as they represent complete inventory failures and can
   * trigger customer churn.
   */
  products_with_all_variants_out_of_stock: number &
    tags.Type<"int32"> &
    tags.Minimum<0>;

  /**
   * Count of products having at least one variant with insufficient stock
   * relative to recent sales trends (last 30 days).
   *
   * This metric identifies products with variants whose inventory is below
   * the level needed to meet projected demand based on recent sales velocity.
   * The system calculates the "sufficient stock" threshold by analyzing the
   * average daily sales rate for each variant over the past 30 days and
   * projecting forward based on historical seasonality patterns. A variant is
   * considered insufficient if its current inventory cannot cover expected
   * demand for a predefined number of days (typically 7-14 days based on
   * replenishment lead times). This metric helps identify products that will
   * run out of stock soon, even if they're not currently at zero inventory.
   */
  products_with_insufficient_stock: number &
    tags.Type<"int32"> &
    tags.Minimum<0>;

  /**
   * Directional trend of overall inventory health over the past 90 days based
   * on historical health scores. Determines if inventory management is making
   * progress or facing increasing challenges.
   *
   * This property reflects the trajectory of the overall_health_score over
   * the previous 90-day period, calculated by comparing the current score to
   * scores from the same day each month over the past three months. The trend
   * is determined using linear regression analysis on the historical health
   * scores. A trend of 'improving' indicates that inventory management
   * interventions are working effectively, 'stable' indicates consistent
   * inventory control, and 'deteriorating' indicates that inventory issues
   * are growing despite current practices. This trend metric helps identify
   * whether current inventory management strategies are effective or if new
   * approaches are needed.
   */
  inventory_health_trend: "improving" | "stable" | "deteriorating";

  /**
   * List of prioritized recommendations for inventory optimization,
   * procurement planning, and supply chain adjustments.
   *
   * This array contains specific, actionable directives issued to inventory
   * and procurement teams based on the analysis of current inventory
   * conditions and historical trends. The recommendations are not generic
   * advice but precise instructions derived from the specific metrics
   * reported in this schema. Each recommendation is optimized for
   * implementation within the constraints of the business, including budget,
   * supplier relationships, and operational capacity. These recommendations
   * are intended to be executable by inventory managers without requiring
   * additional interpretation or analysis.
   */
  recommendations: string[];

  /**
   * Detailed inventory health analysis for each individual product in the
   * catalog.
   *
   * This array contains comprehensive health assessments for every product in
   * the catalog, with each item providing detailed metrics including
   * per-product inventory health scores, variant-specific stock levels, sales
   * velocity data, and specific reasons for any health issues. Each product
   * breakdown includes:
   *
   * - Individual product health score
   * - Breakdown of variant inventory statuses (all variants in stock, some
   *   variants out of stock, etc.)
   * - Sales velocity per variant
   * - Days of inventory remaining for each variant
   * - Specific recommendations for each product based on its unique demand and
   *   inventory patterns
   *
   * This level of detail allows procurement managers to drill down into
   * specific product categories and make informed decisions about which
   * products need immediate attention, which can wait for planned
   * replenishment cycles, and which products may need pricing or promotional
   * adjustments to clear excess inventory.
   */
  product_breakdown: IShoppingMallInventoryHealthProductBreakdown[];
};
